import {gamesTableNav} from './shutters-ui.mjs';
import {drawnHowtoTag} from './drawn-howto.mjs';
import {rowDials} from './ribbon-rows-content.mjs';
import {rowsView,rowsPosition,afterRowMove,takeRows,brambleRowMove,dealRows,readableRowNote,readableRowsLesson,bundleCounts,showRowBundles,practiceRows,startRows,chooseRow,chooseRowCount,clearRowDraft,moveRows,explainRows,keepRowNote,resumeRows,removeRowRecord} from './ribbon-rows-core.mjs';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let visit=null;
export const resetRowsVisit=()=>{visit=null;};
const result=g=>{const p=rowsPosition(g);if(!p)return 'Earlier game';const kind=p.left.length===3?'Three rows':'Two rows';return `${kind} (started ${g.start.join(', ')}): ${p.winner?(p.winner==='child'?g.source.childWin:g.source.brambleWin):`${p.left.join(', ')} ribbons left; ${p.turn==='child'?'your':'Bramble’s'} turn`}`;};
function mat(left,draft={row:null,take:null},interactive=false){return `<div class="rows-mat">${left.map((n,row)=>{
 const chosen=draft.row===row,body=`<span class="rows-row-label">Row ${row+1}<strong>${n} ${n===1?'ribbon':'ribbons'}</strong></span><span class="rows-knots" aria-hidden="true">${Array.from({length:7},(_,i)=>`<span class="rows-slot${i<n?' filled':''}${chosen&&draft.take!==null&&i>=n-draft.take&&i<n?' taking':''}">${i<n?'<i class="rows-knot"></i>':''}</span>`).join('')}</span>`;
 return interactive?`<button type="button" class="rows-row row-${row}${chosen?' chosen':''}" data-rows-row="${row}" aria-pressed="${chosen}" aria-label="Row ${row+1}, ${n} ${n===1?'ribbon':'ribbons'}${chosen?', chosen':''}" aria-describedby="rows-draft"${n===0?' disabled':''}>${body}</button>`:`<div class="rows-row row-${row}">${body}</div>`;
 }).join('')}</div>`;}
function setup(v){const g=v.current,count=g?.start.length??2,options=n=>Array.from({length:7},(_,i)=>`<option value="${i+1}"${n===i+1?' selected':''}>${i+1}</option>`).join('');return `<header class="rows-heading"><h1 id="rows-title" tabindex="-1">Ribbon Rows</h1><p>“Two rows or three. One rival,” says Bramble. “What will you leave for me?”</p></header>${drawnHowtoTag('rows-play')}<div data-rows-preview>${mat(g?.start??[5,3])}</div><form data-rows-start><label>Which variation?<select name="rowCount"><option value="2"${count===2?' selected':''}>Two rows: matching</option><option value="3"${count===3?' selected':''}>Three rows: bundles</option></select></label><div class="rows-setup-pair">${[0,1,2].map(row=>`<label${row===2?' data-rows-third':''}${row>=count?' hidden':''}>Row ${row+1} ribbons<select name="row${row+1}">${options(g?.start[row]??[5,3,4][row])}</select></label>`).join('')}</div><button type="button" data-rows-deal>Deal rows for me</button><p id="rows-dealt" role="status">Choose the row lengths, or deal a different set.</p><label>Who starts?<select name="first"><option value="child"${g?.first!=='bramble'?' selected':''}>I’ll go first</option><option value="bramble"${g?.first==='bramble'?' selected':''}>Bramble goes first</option></select></label><label>How should Bramble play?<select name="dial">${rowDials.map(([id,label])=>`<option value="${id}"${(g?.dial??'attention')===id?' selected':''}>${esc(label)}</option>`).join('')}</select></label><p>${rowDials.map(([,label,line])=>`${esc(label)}: ${esc(line)}`).join('<br>')}</p><p>Take any number from one row. Whoever takes the last ribbon wins. With best play, who starts can decide the game. Bramble can explain why.</p><button class="primary" type="submit">Put the ribbons on the table</button>${g?'<button type="button" data-rows-back>Return to our waiting game</button>':''}</form>`;}
export function rowsBundleTable(left,label='Current ribbons, before any chosen take'){
 const counts=bundleCounts(left);
 return `<div class="rows-bundle-view"><table class="rows-bundles"><caption>${esc(label)}</caption><thead><tr><th scope="col">Row</th>${counts.map(c=>`<th scope="col">${c.size}<small>ribbons</small></th>`).join('')}</tr></thead><tbody>${left.map((n,row)=>`<tr class="row-${row}"><th scope="row">Row ${row+1}<small>${n} = ${[4,2,1].filter(size=>n&size).join(' + ')||'0'}</small></th>${counts.map(c=>`<td>${n&c.size?`<span class="rows-bundle" role="img" aria-label="One bundle of ${c.size} ${c.size===1?'ribbon':'ribbons'}"><span class="rows-bundle-knots" aria-hidden="true">${'<i class="rows-knot"></i>'.repeat(c.size)}</span><b aria-hidden="true">${c.size}</b></span>`:'<span class="rows-no-bundle">none</span>'}</td>`).join('')}</tr>`).join('')}</tbody><tfoot><tr><th scope="row">Partners</th>${counts.map(c=>`<td data-bundle-size="${c.size}"><strong>${c.count} ${c.count===1?'bundle':'bundles'}</strong><span>${Math.floor(c.count/2)} ${Math.floor(c.count/2)===1?'pair':'pairs'}</span><span>${c.count%2?'1 unpaired':'none unpaired'}</span></td>`).join('')}</tr></tfoot></table><p class="rows-pair-status">${counts.every(c=>c.count%2===0)?'All bundle sizes pair.':'At least one bundle size has no partner.'}</p></div>`;
}
const supportSummary=g=>g.support.map(t=>{
 if(t==='explanation-before')return 'earlier explanation familiarity';if(t==='bundles-before')return 'earlier bundle-picture familiarity';
 if(['explanation','bundles'].includes(t)){const at=g[t==='explanation'?'explanationAt':'bundlesAt'],name=t==='explanation'?'explanation':'bundle picture';return Number.isInteger(at)?`${name} opened ${rowsPosition(g)?.winner&&at===g.moves.length?'after the ending':`at move ${at}`}`:`${name} timing not recorded`;}
 return 'other support details kept';
}).join('; ');
function board(g,practice=false){
 const p=rowsPosition(g),d=g.draft,last=g.moves.at(-1),canChoose=!p.winner&&p.turn==='child';
 const message=p.winner?(p.winner==='child'?g.source.childWin:g.source.brambleWin):p.turn==='bramble'?'Bramble’s turn. Ready to see her move?':'Your turn. Choose a row, then how many ribbons to take.';
 const draft=d.row===null?'Choose one of the rows.':d.take===null?`Row ${d.row+1} is chosen. How many of its ${p.left[d.row]} ribbons will you take?`:`Row ${d.row+1}: ${p.left[d.row]} − ${d.take} = ${p.left[d.row]-d.take} left. You can still change your choice.`;
 const equation=last?`${last.who==='child'?'You':'Bramble'} took ${last.take} from Row ${last.row+1}: ${p.left[last.row]+last.take} − ${last.take} = ${p.left[last.row]}.`:'The ribbons are ready.';
 return `<header class="rows-heading"><h1 id="rows-title" tabindex="-1">${esc(g.source.title)}</h1><p>${esc(g.source.rule)}</p>${practice?'<p class="rows-practice-label">Practice with a supplied strategy. Your waiting game stays as it was; no practice result is kept.</p>':''}</header>${practice?'':drawnHowtoTag('rows-play')}<h2 id="rows-turn" role="status" aria-live="polite" tabindex="-1">${esc(message)}</h2>${mat(p.left,d,canChoose)}<p class="rows-last">${equation}</p>${canChoose?`<p id="rows-draft" role="status" aria-live="polite" tabindex="-1">${draft}</p>${d.row!==null?`<div class="rows-counts" role="group" aria-label="How many ribbons?"><span>Take from Row ${d.row+1}:</span>${Array.from({length:p.left[d.row]},(_,i)=>`<button type="button" data-rows-count="${i+1}" aria-pressed="${d.take===i+1}" aria-describedby="rows-draft">${i+1}</button>`).join('')}</div>`:''}<div class="rows-actions"><button class="primary" type="button" data-rows-take${d.take===null?' disabled':''}>Take these ribbons</button><button type="button" data-rows-clear${d.row===null?' disabled':''}>Clear my choice</button></div>`:!p.winner?'<button type="button" class="primary" data-rows-bramble>Let Bramble play</button>':'<p>That game is finished. A different start or a different plan can change what happens.</p>'}${p.winner&&!practice?`<form data-rows-note><label>A thought to keep <span>(optional)</span><textarea name="note" rows="2" maxlength="1000" placeholder="I noticed… Next time I’ll try…"${g.noteKept?' disabled':''}></textarea></label><button type="submit"${g.noteKept?' disabled':''}>${g.noteKept?'Note kept':'Keep a game note'}</button></form>`:''}${p.left.length===3?`<div class="rows-bundle-option"><button type="button" data-rows-bundles aria-expanded="${visit.bundles}" aria-controls="rows-bundle-panel">${visit.bundles?'Hide bundles':'Show bundles'}</button>${visit.bundles?`<div id="rows-bundle-panel"><p>This supplied picture shows the actual board, before your chosen take. Pair only bundles of the same size.</p>${rowsBundleTable(p.left)}</div>`:''}</div>`:''}${practice?'<button type="button" data-rows-end-practice>Back to Bramble’s explanation</button><button type="button" data-rows-back>Return to our waiting game</button>':`<div class="rows-actions"><button type="button" data-rows-new>New game / change the rows</button><button type="button" data-rows-explain>Bramble explains her plan</button></div>`}${g.moves.length?`<details><summary>How this game went</summary><ol>${g.moves.map(m=>`<li>${m.who==='child'?'You':'Bramble'} took ${m.take} from Row ${m.row+1}.</li>`).join('')}</ol></details>`:''}`;
}
function lesson(v){const l=v.root?.lesson;if(!readableRowsLesson(l))return '<p>This earlier explanation is unavailable. Your game stays unchanged.</p><button type="button" data-rows-back>Return to game</button>';
 const f=l.source.frames[l.step],three=f.rows.length===3,last=l.source.frames.length-1;let left=f.rows;
 const diagrams=[three?rowsBundleTable(left,'Before the take'):mat(left)];
 for(let i=0;i<f.moves.length;i++){const m=f.moves[i],old=left;left=afterRowMove(left,m);diagrams.push(`<p class="rows-example-moves">${m.who==='child'?'You':'Bramble'} take${m.who==='bramble'?'s':''} ${m.take} from Row ${m.row+1}: ${old[m.row]} − ${m.take} = ${left[m.row]}.</p>`);if(three)diagrams.push(rowsBundleTable(left,i<f.moves.length-1?'Middle: before Bramble replies':'After the take'));}
 if(!three&&f.moves.length)diagrams.push(mat(left));
 const nav=`<nav class="rows-actions${three?' rows-lesson-nav':''}" aria-label="Ribbon Rows explanation"><button type="button" data-rows-step="${l.step-1}"${l.step===0?' disabled':''}>Back</button><span>Thought ${l.step+1} of ${l.source.frames.length}</span>${l.step<last?`<button type="button" class="primary" data-rows-step="${l.step+1}">Next thought</button>`:'<button type="button" class="primary" data-rows-practice>Try this example</button>'}</nav>`;
 return `<header class="rows-heading"><h1 id="rows-title" tabindex="-1">Bramble explains</h1><p>${three?'Three-row bundles':'Two-row matching'}: a supplied plan. Your waiting game stays as it was.</p></header>${three?nav:''}${three?`<p class="rows-thought" id="rows-thought" tabindex="-1">${esc(f.text)}</p>`:''}${diagrams.join('')}${!three?`<p class="rows-thought" id="rows-thought" tabindex="-1">${esc(f.text)}</p>${nav}`:''}<button type="button" data-rows-back>Return to our waiting game</button>`;
}
function history(r){if(!r)return '';return `<details class="rows-history"><summary>Earlier games and notes</summary><p>No wins or losses are added up. Download a copy before removing anything you want to keep.</p>${r.earlier.map((g,i)=>rowsPosition(g)?`<div class="rows-record"><p>${esc(result(g))}</p><button type="button" data-rows-resume="${i}">Resume</button><button type="button" data-rows-remove="earlier:${i}">Remove game</button></div>`:'<p>An earlier record stays unchanged in your download.</p>').join('')}${r.notes.map((n,i)=>readableRowNote(n)?`<div class="rows-record"><p>${esc(n.text||'A game we played.')}<br><small>${esc(result(n.game))}${n.game.support.length?` · ${esc(supportSummary(n.game))}`:''}</small></p><button type="button" data-rows-remove="notes:${i}">Remove note</button></div>`:'<p>An earlier note stays unchanged in your download.</p>').join('')}<a href="#notes">Download from Grown-up notes</a></details>`;}
export function rowsPage(state,owner){
 if(!visit||visit.state!==state||visit.owner!==owner)visit={state,owner,page:'game',practice:null,remove:null,message:'',bundles:false};
 const v=rowsView(state),content=visit.practice?board(visit.practice,true):visit.page==='lesson'?lesson(v):visit.page==='setup'||!v.current?setup(v):board(v.current);
 return `<section class="ribbon-rows-page" data-rows-root><a class="back" href="#orchard">Back to the Orchard</a>${gamesTableNav('rows')}${v.unsupported||v.root?.current&&!v.current?'<p class="rows-warning">Earlier Ribbon Rows work stays unchanged in your download. Starting a new game will retain it.</p>':''}${content}${visit.remove?'<div class="rows-confirm" role="group" aria-label="Remove this record?"><p>Remove only this record? Download a copy first if you want to keep it.</p><button type="button" data-rows-confirm>Remove this record</button><button type="button" data-rows-cancel>Keep it</button></div>':''}<p id="rows-status" role="status" tabindex="-1">${esc(visit.message)}</p>${!v.unsupported?history(v.root):''}<p class="tiny">No timer or running score. Leave and return whenever you like.</p></section>`;
}
export function rowsNotes(state){if(!Object.hasOwn(state,'ribbonRows'))return '';const v=rowsView(state);return `<details class="panel"><summary>Ribbon Rows: matching and strategy notes</summary><p>Who took the last ribbon is not a math level. Bramble’s dial is not a math level either; it changes how she plays. Supplied explanations and their timing stay separate from game moves; practice results are not saved.</p><p>${esc(v.current?result(v.current):'Earlier work stays in your download.')}</p><a href="#orchard/games/rows">Return to Ribbon Rows</a></details>`;}
export function bindRows(state,ctx){
 const root=document.querySelector('[data-rows-root]');if(!root||!visit)return;const captured=visit,owner=ctx.explorerId(),rootRef=state.ribbonRows,practiceRef=visit.practice;
 const live=()=>root.isConnected&&document.querySelector('[data-rows-root]')===root&&location.hash==='#orchard/games/rows'&&visit===captured&&visit.state===state&&visit.practice===practiceRef&&ctx.isActive()&&ctx.explorerId()===owner&&state.ribbonRows===rootRef;
 const render=(selector='#rows-turn')=>{ctx.render();ctx.focus(selector);};
 const act=(fn,selector='#rows-turn')=>{if(!live())return;visit.message='';if(!fn()){const p=root.querySelector('#rows-status');p.textContent='This change cannot fit safely in your notes. Your work is unchanged. Download a copy, then remove chosen earlier games or notes to free space. A separate explorer can start fresh.';p.focus();return;}visit.remove=null;ctx.save();render(selector);};
 const edit=(saved,temporary,selector)=>{if(!live())return;if(visit.practice){const next=structuredClone(visit.practice);if(!temporary(next)||!rowsPosition(next))return;visit.practice=next;render(selector);}else act(saved,selector);};
 root.querySelector('[data-rows-start]')?.addEventListener('submit',e=>{e.preventDefault();if(!live())return;const f=new FormData(e.target);act(()=>startRows(state,{start:Array.from({length:Number(f.get('rowCount'))},(_,i)=>Number(f.get('row'+(i+1)))),first:f.get('first'),dial:f.get('dial')},ctx.canExport)&&((visit.page='game'),(visit.bundles=false),true));});
 const form=root.querySelector('[data-rows-start]');
 const preview=()=>{if(!live()||!form)return;const count=Number(form.elements.rowCount.value);form.querySelector('[data-rows-third]').hidden=count!==3;root.querySelector('[data-rows-preview]').innerHTML=mat(Array.from({length:count},(_,i)=>Number(form.elements['row'+(i+1)].value)));};
 form?.addEventListener('change',preview);
 root.querySelector('[data-rows-deal]')?.addEventListener('click',()=>{if(!live())return;const pair=dealRows(Math.random,Number(form.elements.rowCount.value));pair.forEach((n,i)=>form.elements['row'+(i+1)].value=n);preview();root.querySelector('#rows-dealt').textContent=`Dealt ${pair.join(', ')}. Start when you are ready, or change them.`;});
 root.querySelector('[data-rows-bundles]')?.addEventListener('click',()=>{if(!live())return;if(visit.bundles){visit.bundles=false;render('[data-rows-bundles]');return;}if(visit.practice){const g=visit.practice;if(!g.support.includes('bundles')){g.support.push('bundles');g.bundlesAt=g.moves.length;}visit.bundles=true;render('[data-rows-bundles]');}else act(()=>showRowBundles(state,ctx.canExport)&&((visit.bundles=true),true),'[data-rows-bundles]');});
 root.querySelectorAll('[data-rows-row]').forEach(b=>b.onclick=()=>{const row=Number(b.dataset.rowsRow);edit(()=>chooseRow(state,row,ctx.canExport),g=>{const p=rowsPosition(g);if(p.winner||p.turn!=='child'||!p.left[row])return false;if(g.draft.row!==row)g.draft={row,take:null};return true;},'#rows-draft');});
 root.querySelectorAll('[data-rows-count]').forEach(b=>b.onclick=()=>{const take=Number(b.dataset.rowsCount);edit(()=>chooseRowCount(state,take,ctx.canExport),g=>{g.draft.take=take;return true;},`[data-rows-count="${take}"]`);});
 root.querySelector('[data-rows-clear]')?.addEventListener('click',()=>edit(()=>clearRowDraft(state,ctx.canExport),g=>{g.draft={row:null,take:null};return true;},'#rows-draft'));
 root.querySelector('[data-rows-take]')?.addEventListener('click',()=>edit(()=>moveRows(state,'child',ctx.canExport)&&((visit.bundles=false),true),g=>{const n=takeRows(g,'child',g.draft.row,g.draft.take);if(!n)return false;Object.assign(g,n);visit.bundles=false;return true;}));
 root.querySelector('[data-rows-bramble]')?.addEventListener('click',()=>edit(()=>moveRows(state,'bramble',ctx.canExport)&&((visit.bundles=false),true),g=>{const m=brambleRowMove(g),n=m&&takeRows(g,'bramble',m.row,m.take);if(!n)return false;Object.assign(g,n);visit.bundles=false;return true;}));
 root.querySelector('[data-rows-new]')?.addEventListener('click',()=>{if(live()){visit.page='setup';visit.remove=null;visit.bundles=false;render('#rows-title');}});
 root.querySelector('[data-rows-back]')?.addEventListener('click',()=>{if(live()){visit.page='game';visit.practice=null;visit.remove=null;visit.bundles=false;render('#rows-title');}});
 root.querySelector('[data-rows-explain]')?.addEventListener('click',()=>act(()=>explainRows(state,0,ctx.canExport)&&((visit.page='lesson'),(visit.bundles=false),true),'#rows-title'));
 root.querySelectorAll('[data-rows-step]').forEach(b=>b.onclick=()=>act(()=>explainRows(state,Number(b.dataset.rowsStep),ctx.canExport),'#rows-thought'));
 root.querySelector('[data-rows-practice]')?.addEventListener('click',()=>{if(!live())return;const l=rowsView(state).root?.lesson;if(!readableRowsLesson(l))return;visit.practice=practiceRows(l.source);visit.bundles=false;render('#rows-title');});
 root.querySelector('[data-rows-end-practice]')?.addEventListener('click',()=>{if(live()){visit.practice=null;visit.page='lesson';visit.bundles=false;render('#rows-title');}});
 root.querySelector('[data-rows-note]')?.addEventListener('submit',e=>{e.preventDefault();act(()=>keepRowNote(state,new FormData(e.target).get('note'),ctx.canExport)&&((visit.message='Your game note is kept.'),true),'#rows-status');});
 root.querySelectorAll('[data-rows-resume]').forEach(b=>b.onclick=()=>act(()=>resumeRows(state,Number(b.dataset.rowsResume),ctx.canExport)&&((visit.page='game'),(visit.practice=null),(visit.bundles=false),true),'#rows-title'));
 root.querySelectorAll('[data-rows-remove]').forEach(b=>b.onclick=()=>{if(live()){visit.remove=b.dataset.rowsRemove;render('[data-rows-cancel]');}});
 root.querySelector('[data-rows-cancel]')?.addEventListener('click',()=>{if(live()){visit.remove=null;render('#rows-title');}});
 root.querySelector('[data-rows-confirm]')?.addEventListener('click',()=>{if(!live()||!visit.remove)return;const [kind,index]=visit.remove.split(':');act(()=>removeRowRecord(state,kind,Number(index),ctx.canExport),'#rows-title');});
}
